INSERT INTO disciplinas (id, nome, semestre, fase, trilha_id, ementa_resumo, ementa_fonte, aplicacao_trabalho, recurso_titulo, recurso_url, entregavel, dominio, arquivada, motivo_arquivamento, visibilidade, sort_order) VALUES ('d5-pensamento-analitico', 'Pensamento Analítico e Análise de Dados', 5, 'cursada', 'dados', 'Estruturação de problemas, estatística descritiva, leitura e visualização de dados para decisão.', 'generica', 'Dimensionar um problema operacional em horas ou volume antes de propor solução. Base do business case do Ciclo 1.', 'Storytelling with Data, Cole Nussbaumer Knaflic (cap. 1 a 4)', NULL, 'Dashboard de 3 a 5 cards que sustenta o business case do Ciclo 1.', 'estudando', 0, NULL, 'publica', 0);
INSERT INTO disciplinas (id, nome, semestre, fase, trilha_id, ementa_resumo, ementa_fonte, aplicacao_trabalho, recurso_titulo, recurso_url, entregavel, dominio, arquivada, motivo_arquivamento, visibilidade, sort_order) VALUES ('d5-arquitetura-computadores', 'Arquitetura e Organização de Computadores', 5, 'cursada', 'cloud', 'Organização de CPU, memória, hierarquia de cache, entrada e saída, representação de dados.', 'generica', 'Entender por que a memória configurada define a CPU de uma função Lambda e o que muda entre x86 e ARM (Graviton).', 'Computer Organization and Design, Patterson e Hennessy', NULL, 'Nota técnica: como memória, vCPU e arquitetura afetam custo e latência de uma Lambda, com teste de 2 configurações.', 'preciso-estudar', 0, NULL, 'publica', 1);
INSERT INTO disciplinas (id, nome, semestre, fase, trilha_id, ementa_resumo, ementa_fonte, aplicacao_trabalho, recurso_titulo, recurso_url, entregavel, dominio, arquivada, motivo_arquivamento, visibilidade, sort_order) VALUES ('d5-modelagem-dados', 'Modelagem de Dados', 5, 'cursada', 'dados', 'Modelo entidade-relacionamento, modelo relacional, normalização, chaves e integridade.', 'generica', 'Ler modelos de pedido, parcela e refund e desenhar chave de partição e GSI no DynamoDB.', 'Fundamentals of Database Systems, Elmasri e Navathe; The DynamoDB Book, Alex DeBrie', NULL, 'Modelo ER e modelo DynamoDB de um domínio fictício de pedidos parcelados, publicados no GitHub.', 'estudando', 0, NULL, 'publica', 2);
INSERT INTO disciplinas (id, nome, semestre, fase, trilha_id, ementa_resumo, ementa_fonte, aplicacao_trabalho, recurso_titulo, recurso_url, entregavel, dominio, arquivada, motivo_arquivamento, visibilidade, sort_order) VALUES ('d5-sistemas-operacionais', 'Sistemas Operacionais', 5, 'cursada', 'cloud', 'Processos, threads, escalonamento, memória virtual, concorrência e sistemas de arquivos.', 'generica', 'Explicar cold start, concorrência e reuso do ambiente de execução na Lambda, e o event loop do Node.js.', 'Operating Systems: Three Easy Pieces, Arpaci-Dusseau (gratuito)', 'https://pages.cs.wisc.edu/~remzi/OSTEP/', 'Nota técnica: ciclo de vida do ambiente de execução da Lambda comparado a processo e thread do SO.', 'preciso-estudar', 0, NULL, 'publica', 3);
