INSERT INTO goals (id, categoria, trilha_id, ciclo_id, titulo, descricao, data_prazo, prioridade, status, icon, progresso, visibilidade) VALUES ('p1-framework-aceite', 'Cloud AWS', 'cloud', 'ciclo-1', 'Framework de aceite para entrega de integrações', 'Critérios para entregar uma integração de e-commerce à operação: credenciais, paridade entre sandbox e produção, webhooks, reconciliação, segurança, observabilidade e documentação, com três níveis de severidade.', '2026-10-30', 'Baixa', 'Em progresso', 'ClipboardCheck', NULL, 'publica');
INSERT INTO goals (id, categoria, trilha_id, ciclo_id, titulo, descricao, data_prazo, prioridade, status, icon, progresso, visibilidade) VALUES ('p2-automacao-llm', 'IA aplicada', 'ia', 'ciclo-1', 'Assistente de IA para diagnóstico de integrações', 'Assistente de diagnóstico definido por entrevista estruturada, com cobertura das principais plataformas de e-commerce, referência à documentação pública das APIs e regras de comportamento. Entrega: escopo, instruções e regras.', '2026-11-15', 'Alta', 'Em progresso', 'Bot', NULL, 'publica');
INSERT INTO goals (id, categoria, trilha_id, ciclo_id, titulo, descricao, data_prazo, prioridade, status, icon, progresso, visibilidade) VALUES ('p3-business-case', 'Dados e SQL', 'dados', 'ciclo-1', 'Análise de impacto de uma correção de integração na conversão', 'Comparação de conversão antes e depois de uma correção de conector, em um grupo de lojistas, com ressalva sobre efeitos anteriores à correção. Resultado: ganho de um dígito percentual de conversão, em análise parcial.', '2026-12-18', 'Alta', 'Em progresso', 'BarChart3', NULL, 'publica');
INSERT INTO goals (id, categoria, trilha_id, ciclo_id, titulo, descricao, data_prazo, prioridade, status, icon, progresso, visibilidade) VALUES ('p4-postmortem', 'Cloud AWS', 'cloud', 'ciclo-1', 'Postmortem e prevenção de incidentes de integração', 'Investigação de falhas recorrentes de integração (webhook, estorno, bloqueio de rede e processamento em lote), com postmortem padronizado e RFC ou ADR da ação preventiva.', '2026-12-11', 'Média', 'Planejado', 'FileText', NULL, 'publica');
INSERT INTO goals (id, categoria, trilha_id, ciclo_id, titulo, descricao, data_prazo, prioridade, status, icon, progresso, visibilidade) VALUES ('p5-tech-talk', 'Comunicação', NULL, 'ciclo-1', 'Treinamento interno de uso diário de IA', 'Sessão para o time com guia complementar sobre delegação, descrição, dependência crítica e disciplina no uso de IA, com três modos de uso e nove casos práticos.', '2026-12-18', 'Alta', 'Planejado', 'Presentation', NULL, 'publica');
INSERT INTO goals (id, categoria, trilha_id, ciclo_id, titulo, descricao, data_prazo, prioridade, status, icon, progresso, visibilidade) VALUES ('serverless-badge', 'Cloud AWS', 'cloud', 'ciclo-1', 'Badge do AWS Serverless Learning Plan', 'Concluir o learning plan no AWS Skill Builder e passar na avaliação (80% ou mais).', '2026-11-01', 'Média', 'Em progresso', 'Award', NULL, 'publica');
